  'home.tagline': 'Your adaptive learning operating system.',
  'home.signIn': 'Sign in',
  'home.signUp': 'Create account',
  'marketing.seoTitle': 'StudyUS | Don\'t study more. Study better.',
  'marketing.seoDescription': 'StudyUS is an adaptive study coach: it finds what you need, guides you to understand and practise it, and checks that you can do it on your own, remember it and apply it in new situations.',
  'marketing.h1': 'Don\'t study more. Study better.',
  'marketing.subhead': 'StudyUS is your study coach. It finds what you need, focuses you on what matters today and checks that you\'ve truly mastered it — without making you repeat what you already know.',
  'marketing.navHowItWorks': 'How it works',
  'marketing.footerTagline': 'Don\'t study more. Study better.',
  'marketing.section1Title': 'It decides what you need',
  'marketing.section1Body': 'StudyUS reads your material, breaks it into concepts, and tells you what to work on next -- you never have to plan your own study.',
  'marketing.section2Title': 'It doesn\'t stop at a right answer',
  'marketing.section2Body': 'A correct answer is a start. StudyUS then checks that you can do it without help, still remember it later, and use it somewhere new.',
  'marketing.section3Title': 'It shows you where you really stand',
  'marketing.section3Body': 'For every concept you see what\'s understood, what\'s proven on your own, what\'s retained, and what still needs work -- based on real evidence, not a score.',
  'marketing.section4Title': 'It adapts to you',
  'marketing.section4Body': 'What you practice, when a concept comes back for review, and what StudyUS asks next all follow your real performance -- not a fixed course everyone runs the same way.',
  'marketing.section5Title': 'Built for real school',
  'marketing.section5Body': 'Track mastery over time and walk into exams -- including IB assessments for Diploma and MYP students -- prepared, not just familiar.',
  'marketing.ctaPrimary': 'Start learning for free',
  'marketing.ctaSecondary': 'See how it works',
  'marketing.faqTitle': 'Frequently asked questions',
  'marketing.faq1Q': 'Is StudyUS an AI chatbot?',
  'marketing.faq1A': 'No. StudyUS is a structured learning system -- it decides what you need, guides the learning, and verifies you can really do it. It isn\'t a chat window you ask questions in.',
  'marketing.faq2Q': 'Is it just flashcards or quizzes?',
  'marketing.faq2A': 'No. Flashcards test recall of isolated facts. StudyUS builds understanding of a concept and then checks you can do it independently, remember it later, and apply it in a new situation.',
  'marketing.faq3Q': 'Does it just make a study schedule?',
  'marketing.faq3A': 'No. A schedule tells you when to study. StudyUS decides what to study, teaches the concepts, and tracks whether you\'re actually improving.',
  'howItWorks.seoTitle': 'How StudyUS works | Learn, practice, prove, remember, apply',
  'howItWorks.seoDescription': 'The StudyUS learning cycle: understand a concept, practice it, prove you can do it independently, retain it over time, and transfer it to new situations.',
  'howItWorks.h1': 'Learn. Practice. Prove. Remember. Apply.',
  'howItWorks.intro': 'StudyUS isn\'t a flashcard app or a chatbot. It\'s a learning cycle that makes sure you actually understand each concept and can use it -- not just recognise it.',
  'howItWorks.step1Title': 'Learn: build a clear mental model',
  'howItWorks.step1Body': 'Every concept is explained clearly, with real examples, so you understand the idea itself -- not a shortcut to memorise it.',
  'howItWorks.step2Title': 'Practice: work with it, with help',
  'howItWorks.step2Body': 'You apply the concept in guided practice, with hints available, until it feels familiar.',
  'howItWorks.step3Title': 'Prove: do it on your own',
  'howItWorks.step3Body': 'StudyUS checks you can do it independently -- no hints -- before it counts the concept as yours.',
  'howItWorks.step4Title': 'Remember: make it stick',
  'howItWorks.step4Body': 'Concepts come back for review at the right time, so what you learned is still there weeks later, not just on the day.',
  'howItWorks.ctaPrimary': 'Start learning with StudyUS',
  'onboarding.title': 'First steps',
  'onboarding.dismiss': 'Hide',
  'onboarding.step1Title': 'Create your first subject',
  'onboarding.step1Body': 'Group what you\'re studying — a class or a course — to get started.',
  'onboarding.step1Cta': 'Create subject',
  'onboarding.step2Title': 'Add content',
  'onboarding.step2Body': 'Upload a PDF or write a concept — StudyUS organizes it automatically.',
  'onboarding.step2Cta': 'Add content',
  'onboarding.step3Title': 'Do your first practice',
  'onboarding.step3Body': 'Answer a short quiz so StudyUS can start measuring your mastery.',
  'onboarding.step3Cta': 'Practice now',
