  // LX-2 entry experience.
  'marketing.stagesTitle': 'How learning works in StudyUS',
  'marketing.stagesIntro': 'Getting an answer right is the start, not the finish. StudyUS moves every concept through the same path.',
  'marketing.stageLearnName': 'Learn',
  'marketing.stageLearnBody': 'Understand the idea itself, clearly explained in your own language.',
  'marketing.stagePracticeName': 'Practice',
  'marketing.stagePracticeBody': 'Work with the concept until it feels familiar, with help available.',
  'marketing.stageProveName': 'Prove',
  'marketing.stageProveBody': 'Show you can do it on your own, without hints.',
  'marketing.stageRetainName': 'Retain',
  'marketing.stageRetainBody': 'Come back to it later so it actually sticks.',
  'marketing.stageTransferName': 'Transfer',
  'marketing.stageTransferBody': 'Use it in a new situation you haven\'t seen before.',
  'howItWorks.step5Title': 'Apply: use it somewhere new',
  'howItWorks.step5Body': 'Once a concept is solid, StudyUS asks you to apply it in an unfamiliar situation -- the real test of understanding, not just recall.',
  'signup.framingTitle': 'Create your StudyUS account',
  'signup.framingBody': 'Next you\'ll add your first subject, and StudyUS starts building your learning path.',
  'signup.next': 'After signing up: add a subject -> start learning.',
  'onboarding2.title': 'Welcome to StudyUS',
  'onboarding2.intro': 'StudyUS builds and adapts your learning path for you. Here\'s what to expect.',
  'onboarding2.whatTitle': 'What StudyUS does',
  'onboarding2.whatBody': 'It works out what you need next, guides you through learning it, and checks that you can really do it -- understand it, do it on your own, remember it, and apply it.',
  'onboarding2.needTitle': 'What StudyUS needs from you',
  'onboarding2.needBody': 'One thing to start: a subject. Add what you\'re studying and upload or write the material -- that\'s what StudyUS learns from.',
  'onboarding2.nextTitle': 'What happens after setup',
  'onboarding2.nextBody': 'StudyUS reads your material, breaks it into concepts, and tells you exactly what to do first on your Today page. You never have to plan it yourself.',
  'onboarding2.cta': 'Add my first subject',
  'onboarding2.laterProfile': 'You can add your school and curriculum later from your profile.',
