  'onboarding2.whatTitle': 'Was StudyUS macht',
  'onboarding2.whatBody': 'Es ermittelt, was du als Nächstes brauchst, führt dich durchs Lernen und prüft, ob du es wirklich kannst: verstehen, selbstständig anwenden, behalten und übertragen.',
  'onboarding2.needTitle': 'Was StudyUS von dir braucht',
  'onboarding2.needBody': 'Eine Sache zum Start: ein Fach. Füge hinzu, was du lernst, und lade das Material hoch oder schreibe es -- daraus lernt StudyUS.',
  'onboarding2.nextTitle': 'Was nach der Einrichtung passiert',
